import events from './events.json' with {type:'json'};

export async function listTools() {
  return [{
    name: 'events_list',
    description: 'List events with pagination',
    inputSchema: {
      type: 'object',
      properties: {
        cursor: { type: 'string', description: 'Opaque cursor for pagination' },
        page_size: { type: 'integer', minimum: 1, maximum: 3, default: 2, description: 'Number of events per page (1-3)' }
      },
      additionalProperties: false
    }
  }];
}

export async function callTool(name, args) {
  if (name !== 'events_list') {
    throw new Error('Unknown tool');
  }

  // Validate no extra fields
  const allowedKeys = ['cursor', 'page_size'];
  for (const key of Object.keys(args)) {
    if (!allowedKeys.includes(key)) {
      throw new Error(`Unexpected field: ${key}`);
    }
  }

  // Validate page_size
  let pageSize = 2; // default
  if ('page_size' in args) {
    pageSize = args.page_size;
    if (typeof pageSize !== 'number' || !Number.isInteger(pageSize) || pageSize < 1 || pageSize > 3) {
      throw new Error('page_size must be an integer between 1 and 3');
    }
  }

  // Validate and decode cursor
  let startIndex = 0;
  if ('cursor' in args) {
    if (typeof args.cursor !== 'string') {
      throw new Error('cursor must be a string');
    }
    try {
      const decoded = Buffer.from(args.cursor, 'base64').toString('utf-8');
      startIndex = parseInt(decoded, 10);
      if (isNaN(startIndex) || startIndex < 0 || startIndex >= events.length) {
        throw new Error('Invalid cursor');
      }
    } catch {
      throw new Error('Invalid cursor');
    }
  }

  // Slice events
  const page = events.slice(startIndex, startIndex + pageSize);
  const nextIndex = startIndex + pageSize;
  const hasMore = nextIndex < events.length;

  const result = { events: page };
  if (hasMore) {
    result.next_cursor = Buffer.from(String(nextIndex)).toString('base64');
  }

  return { content: [{ type: 'text', text: JSON.stringify(result) }] };
}
